    {t="C", q=7842, n="Another Message to the Wildhammer", pn="Mais uma mensagem para os Martelo Feroz", lvl=48, req=44, xp=5450, cc=10, m=1425, x=16.6, y=51.6, ot="i", ahead={{q=7830, n="Avenging the Fallen", pn="Vingar os caídos", i="Skylord Plume", ip="Pluma de Senhor Celeste", c=1, qi=true}}, obj="Otho Moji'ko at Revantusk Village in the Hinterlands wants you to bring him 10 Long Elegant Feathers from the gryphons that inhabit the Hinterlands. Return to him once this task is complete.  Gryphons are known to inhabit every region of the Hinterlands.", pobj="Joho'sér Mujik'ka da Aldeia Revatusco, que fica nas Terras Agrestes, quer que você leve para ele 10 Penas Longas Elegantes extraídas dos grifos que habitam as Terras Agrestes. Quando terminar, fale novamente com ele.  Grifos podem ser encontradas em todas as regiões das Terras Agrestes.", f={"coleta","drop"}},
    {t="C", q=7849, n="Separation Anxiety", pn="Angústia da separação", lvl=50, req=46, xp=5900, m=1425, x=58.56, y=64.76, ot="i", objs={{n="Huntsman Malkhor's Skull", p="Crânio do Guarda-caça Malkhor", m=1425, x=58.56, y=64.76},{n="Huntsman Malkhor's Bones", p="Ossos do Guarda-caça Malkhor", m=1425, x=62.11, y=75.35}}, obj="Huntsman Markhor at Revantusk Village in the Hinterlands wants you to recover his twin brother's remains. Find and return Huntsman Malkhor's Skull and Huntsman Malkhor's Bones to Huntsman Markhor.  Markhor mentioned that his brother's remains were fed to the oozes and wolves of the Vilebranch. He also mentioned that there is a refuse pit filled with oozes in Jintha'alor as well as a wolf den. Both of these places are near the top of the temple.", pobj="O Guarda-caça Markhor da Aldeia Revatusco, que fica nas Terras Agrestes, quer que você encontre os restos mortais do irmão gêmeo dele. Encontre o Crânio do Guarda-caça Malkhor e os Ossos do Guarda-caça Malkhor e leve-os para o Guarda-caça Markhor.  Markhor mencionou que os restos mortais foram deixados para os lobos e as gosmas dos Ramatorpe. Também disse que tem um fosso cheio de gosmas em Jintha'Alor, assim como um covil de lobos. Ambos lugares ficam perto do topo do templo."},
    {t="C", q=7850, n="Dark Vessels", pn="Recipientes negros", lvl=50, req=46, xp=5900, m=1425, x=62.38, y=71.62, ot="i", obj="Primal Torntusk at Revantusk Village in the Hinterlands wants you to recover 10 Vessels of Tainted Blood from Jintha'alor. Return to Primal Torntusk when this task is complete.", pobj="Primeva Presa-arrancada da Aldeia Revatusco, que fica nas Terras Agrestes, quer que você encontre 10 Recipientes com Sangue Maculado em Jintha'Alor. Quando terminar, fale novamente com Primeva Presa-arrancada."},
    {t="C", q=4787, n="The Ancient Egg", pn="O ovo velho", lvl=50, req=40, xp=5900, m=1425, x=57.58, y=86.79, ot="i", obj="Bring the Ancient Egg to Yeh'kinya in Tanaris.", pobj="Leve o Ovo Velho para Yeh'kinya, em Tanaris.", f={"long"}},
