    {t="C", q=7862, n="Job Opening: Guard Captain of Revantusk Village", pn="Temos vagas: Capitão da Guarda da Aldeia Revatusco", lvl=51, req=46, xp=6100, m=1425, x=62.14, y=70.2, ot="k", objs={{n="Vilebranch Berserker", p="Berserker Ramatorpe", m=1425, x=63.56, y=69.97},{n="Vilebranch Shadow Hunter", p="Caçador Sombrio Ramatorpe", m=1425, x=63.18, y=73.02},{n="Vilebranch Blood Drinker", p="Bebe-sangue Ramatorpe", m=1425, x=62.86, y=78.16},{n="Vilebranch Soul Eater", p="Devorador de Almas Ramatorpe", m=1425, x=59.98, y=71.48}}, obj="You have been tasked with the decimation of 20 Vilebranch Berserkers, 20 Vilebranch Shadow Hunters, 20 Vilebranch Blood Drinkers, and 20 Vilebranch Soul Eaters.  Should you complete this task, return to Primal Torntusk at Revantusk Village in the Hinterlands.", pobj="Você recebeu a missão de dizimar 20 Berserkers Ramatorpe, 20 Caçadores Sombrios Ramatorpe, 20 Bebe-sangue Ramatorpe e 20 Devoradores de Almas Ramatorpe.  Caso conclua a missão, fale com Primeva Presa-arrancada na Aldeia Revatusco, que fica nas Terras Agrestes.", f={"elite"}},
    {t="C", q=7861, n="Wanted: Vile Priestess Hexx and Her Minions", pn="Procura-se: Sacerdotisa Torpe Bagata e seus lacaios", lvl=51, req=46, xp=6100, m=1425, x=55.99, y=82.03, ot="k", objs={{n="Vile Priestess Hexx", p="Sacerdotisa Torpe Bagata", m=1425, x=59.47, y=78.26},{n="Vilebranch Aman'zasi Guard", p="Guarda Aman'zasi Ramatorpe", m=1425, x=55.99, y=82.03}}, obj="You have been ordered to slay Vile Priestess Hexx and 20 Vilebranch Aman'zasi Guards. See Primal Torntusk at Revantusk Village in the Hinterlands once this task is complete.  Vile Priestess Hexx and the Aman'zasi Guards can be found atop Jintha'alor in the Hinterlands.", pobj="Você recebeu ordens de matar a Sacerdotisa Torpe Bagata e 20 Guardas Aman'zasi Ramatorpe. Quando terminar, procure Primeva Presa-arrancada, na Aldeia Revatusco, que fica nas Terras Agrestes.  Você pode encontrar a Sacerdotisa Torpe Bagata e os Guardas Aman'zasi no alto de Jintha'Alor, nas Terras Agrestes.", f={"elite"}},
